import {Chess} from './vendor/chess.js';
import {families,categoryOf,titleOf,variationOf,descriptionOf,searchable,selectFeatured} from './catalog.js';
import {buildOpeningTree,isPrefix,firstDifferentStep,moveNumber,commonVariations} from './opening-tree.js';
import {initOpponent} from './opponent.js';
const opponent=initOpponent();
const $=s=>document.querySelector(s);
const icons={book:'<path d="M4 4h6a3 3 0 0 1 2 1 3 3 0 0 1 2-1h6v15h-6a3 3 0 0 0-2 1 3 3 0 0 0-2-1H4zM12 5v15"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3l-5.6 2.9 1.1-6.2L3 9.6l6.2-.9z"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5z"/>',external:'<path d="M14 4h6v6M20 4l-9 9M10 5H5v14h14v-5"/>',layers:'<path d="m3 7 9-5 9 5-9 5zM3 12l9 5 9-5M3 17l9 5 9-5"/>',shuffle:'<path d="M3 7h3c5 0 7 10 12 10h3M17 13l4 4-4 4M3 17h3c2 0 4-3 6-6s4-4 6-4h3M17 3l4 4-4 4"/>',flip:'<path d="M5 8h14l-4-4M19 16H5l4 4M19 8v3M5 16v-3"/>',left:'<path d="m15 5-7 7 7 7"/>',right:'<path d="m9 5 7 7-7 7"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',keyboard:'<rect x="2" y="5" width="20" height="14" rx="2"/><path d="M6 9h1m3 0h1m3 0h1m3 0h1M6 12h1m3 0h1m3 0h1m3 0h1M7 16h10"/>',bulb:'<path d="M9 18h6M10 21h4M8 13a6 6 0 1 1 8 0c-1 1-1 2-1 3H9c0-1 0-2-1-3"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>'};
const icon=(name,extra='')=>`<svg ${extra} viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.book}</svg>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={data:[],featured:[],current:null,step:0,game:new Chess(),flipped:false,view:'library',tab:'featured',panel:'steps',category:'',query:'',eco:'',page:1,tree:null,treeRoot:null,expanded:new Set(),limits:new Map()};
const PAGE_SIZE=30,pieceNames={p:'兵',n:'马',b:'象',r:'车',q:'后',k:'王'},miniCache=new Map(),moveCache=new Map();
let favorites=new Set();
try{const value=JSON.parse(localStorage.getItem('chess-atlas-favorites-v1')||'[]');if(Array.isArray(value))favorites=new Set(value.filter(Number.isInteger));}catch{}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2300);}
function moveDescription(m){let text=m.flags.includes('k')?`王翼易位（王 ${m.from} → ${m.to}）`:m.flags.includes('q')?`后翼易位（王 ${m.from} → ${m.to}）`:`${pieceNames[m.piece]} ${m.from} ${m.captured?'×':'→'} ${m.to}`;if(m.captured)text+=`（吃${pieceNames[m.captured]}${m.flags.includes('e')?'，吃过路兵':''}）`;if(m.promotion)text+=`，升变为${pieceNames[m.promotion]}`;if(m.san.endsWith('#'))text+=' · 将死';else if(m.san.endsWith('+'))text+=' · 将军';return text;}
function movesFor(o){if(!moveCache.has(o.id)){const game=new Chess();moveCache.set(o.id,o.moves.map(san=>{const move=game.move(san);return {...move,description:moveDescription(move)};}));}return moveCache.get(o.id);}
function miniature(o){if(miniCache.has(o.id))return miniCache.get(o.id);const game=new Chess();o.moves.forEach(m=>game.move(m));let html='<span class="mini-board" aria-hidden="true">';for(let r=8;r>=1;r--)for(let f=0;f<8;f++){const p=game.get('abcdefgh'[f]+r);html+=`<span class="mini-square ${(f+8-r)%2?'dark':''}">${p?`<img src="./pieces/${p.color}${p.type.toUpperCase()}.svg" alt="" loading="lazy">`:''}</span>`;}html+='</span>';miniCache.set(o.id,html);return html;}
function setPanel(panel){state.panel=panel;$('#steps-panel').hidden=panel!=='steps';$('#tree-panel').hidden=panel!=='tree';$('#library-panel').hidden=panel!=='library';document.querySelectorAll('[data-panel]').forEach(el=>{el.classList.toggle('active',el.dataset.panel===panel);el.setAttribute('aria-selected',String(el.dataset.panel===panel));});}
function renderSelectedFavorite(){if(!state.current)return;const saved=favorites.has(state.current.id);$('#favorite-selected').classList.toggle('is-favorite',saved);$('#favorite-selected').setAttribute('aria-label',saved?'取消收藏当前开局':'收藏当前开局');$('#favorite-selected').setAttribute('aria-pressed',String(saved));}
function toggleFavorite(id){favorites.has(id)?favorites.delete(id):favorites.add(id);try{localStorage.setItem('chess-atlas-favorites-v1',JSON.stringify([...favorites]));toast(favorites.has(id)?'已加入收藏':'已取消收藏');}catch{toast('浏览器未允许存储，收藏仅在本次浏览保留');}$('#favorite-count').textContent=favorites.size;renderList();renderSelectedFavorite();}
function results(){let items=state.view==='favorites'?state.data.filter(o=>favorites.has(o.id)):(state.tab==='featured'&&!state.query&&!state.eco&&!state.category)?state.featured:state.data;if(state.category)items=items.filter(o=>categoryOf(o)===state.category);if(state.eco)items=items.filter(o=>o.eco.startsWith(state.eco));if(state.query){const terms=state.query.toLowerCase().replace(/\d+\.(\.\.)?/g,' ').split(/\s+/).filter(Boolean);items=items.filter(o=>terms.every(term=>o.search.includes(term)));}return items;}
function renderList(){
 const items=results(),pages=Math.max(1,Math.ceil(items.length/PAGE_SIZE));state.page=Math.min(state.page,pages);const slice=items.slice((state.page-1)*PAGE_SIZE,state.page*PAGE_SIZE);
 $('#result-count').textContent=items.length.toLocaleString();$('#explorer-title').childNodes[0].textContent=state.view==='favorites'?'我的收藏':'探索开局';$('#list-caption').textContent=state.view==='favorites'?'收藏的开局':state.query?'找到了这些开局与变化':state.category?'按第一步，探索不同体系':state.tab==='featured'&&!state.eco?'精选开局':'完整开局库 · 按 ECO 编号排列';
 $('#opening-list').innerHTML=slice.length?slice.map(o=>`<article class="opening-card ${state.current?.id===o.id?'selected':''}" data-id="${o.id}">${miniature(o)}<button class="card-main" aria-label="查看 ${esc(titleOf(o))}"><span class="card-heading"><span class="card-title" title="${esc(titleOf(o))}">${esc(titleOf(o))}</span><span class="eco">${o.eco}</span></span><span class="card-subtitle" title="${esc(o.name)}">${esc(o.name)}</span><span class="card-meta"><span class="card-pgn">${esc(o.pgn)}</span><span class="meta-divider"></span><span>${o.moves.length} 步</span></span></button><span class="card-actions"><button class="card-star ${favorites.has(o.id)?'is-favorite':''}" data-favorite="${o.id}" aria-label="${favorites.has(o.id)?'取消收藏':'收藏'} ${esc(o.name)}" aria-pressed="${favorites.has(o.id)}">${icon('star')}</button>${icon('right','class="card-arrow"')}</span></article>`).join(''):`<div class="empty-state"><span>${state.view==='favorites'?'☆':'♘'}</span>${state.view==='favorites'?'这里还没有收藏的开局':'没有找到匹配的开局'}<p>${state.view==='favorites'?'点击开局旁的星星，就能随时回来复习。':'试试中文、英文名称、ECO 编号，或清除筛选。'}</p><button id="clear-filters">${state.view==='favorites'?'去探索开局':'清除筛选'}</button></div>`;
 $('#page-label').textContent=`${items.length?(state.page-1)*PAGE_SIZE+1:0}–${Math.min(state.page*PAGE_SIZE,items.length)} / ${items.length.toLocaleString()}`;$('#page-prev').disabled=state.page===1;$('#page-next').disabled=state.page>=pages;$('#pagination').hidden=!items.length;
 const categoryNames={e4:'王兵开局 · 1. e4',d4:'后兵开局 · 1. d4',flank:'侧翼开局 · 1. c4 / 1. Nf3',other:'其他第一步'};$('#active-filter').hidden=!state.category;$('#active-filter').innerHTML=state.category?`<button id="remove-category">${categoryNames[state.category]} ×</button>`:'';
 document.querySelectorAll('[data-category]').forEach(el=>el.classList.toggle('active',el.dataset.category===state.category));document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===state.view));document.querySelectorAll('[data-tab]').forEach(el=>{el.classList.toggle('active',el.dataset.tab===state.tab);el.setAttribute('aria-selected',String(el.dataset.tab===state.tab));});document.querySelector('.breadcrumb strong').textContent=state.view==='favorites'?'我的收藏':'开局图书馆';
}
function renderBoard(){
 const g=state.game,last=movesFor(state.current)[state.step-1],files=state.flipped?'hgfedcba':'abcdefgh',ranks=state.flipped?[1,2,3,4,5,6,7,8]:[8,7,6,5,4,3,2,1];let html='';
 for(let r=0;r<8;r++)for(let f=0;f<8;f++){const square=files[f]+ranks[r],p=g.get(square);let cls=`square ${(r+f)%2?'dark':''}`;if(last&&(last.from===square||last.to===square))cls+=' last';if(g.isCheck()&&p?.type==='k'&&p.color===g.turn())cls+=' checked';html+=`<span class="${cls}" role="img" aria-label="${square}${p?' '+(p.color==='w'?'白':'黑')+pieceNames[p.type]:' 空格'}">${p?`<img src="./pieces/${p.color}${p.type.toUpperCase()}.svg" alt="" draggable="false">`:''}${f===0?`<span class="rank">${ranks[r]}</span>`:''}${r===7?`<span class="file">${files[f]}</span>`:''}</span>`;}$('#board').innerHTML=html;
 const topWhite=state.flipped;$('#top-player').textContent=topWhite?'白方':'黑方';$('#bottom-player').textContent=topWhite?'黑方':'白方';const top=$('.board-player .player-avatar'),bottom=$('.bottom-player .player-avatar');top.textContent=topWhite?'♔':'♚';bottom.textContent=topWhite?'♚':'♔';top.className=`player-avatar ${topWhite?'white':'black'}-avatar`;bottom.className=`player-avatar ${topWhite?'black':'white'}-avatar`;$('.board-player .player-tag').textContent=topWhite?'WHITE':'BLACK';$('.bottom-player .player-tag').textContent=topWhite?'BLACK':'WHITE';
 let turn=(g.turn()==='w'?'白方':'黑方')+'走棋';if(g.isCheckmate())turn='将死';else if(g.isDraw())turn='和棋局面';else if(g.isCheck())turn+=' · 被将军';$('#turn-label').innerHTML=`<span class="turn-dot"></span>${turn}`;$('#step-label').textContent=state.step?`第 ${state.step} 步 · ${moveNumber(state.step)}${last.san}`:'初始局面';
}
function renderMoves(){const box=$('#move-list'),scroll=box.scrollTop,infos=movesFor(state.current);$('#move-count').textContent=`${infos.length} 步`;box.innerHTML=`<button class="initial-position ${state.step===0?'active':''}" data-step="0" aria-current="${state.step===0?'step':'false'}"><span>0</span>初始局面</button><ol class="notation-steps">${infos.map((m,i)=>`<li><button class="notation-step ${state.step===i+1?'active':''}" data-step="${i+1}" aria-current="${state.step===i+1?'step':'false'}" aria-label="跳到第 ${i+1} 步 ${m.san}"><span class="step-index">${i+1}</span><span class="step-side ${m.color==='w'?'side-white':'side-black'}">${m.color==='w'?'白方':'黑方'}</span><strong class="step-san">${esc(m.san)}</strong><span class="step-description">${esc(m.description)}</span></button></li>`).join('')}</ol>`;box.scrollTop=scroll;}
function currentPath(){return state.current.moves.slice(0,state.step);}
function updateHash(){history.replaceState(null,'','#'+new URLSearchParams({opening:state.current.id,step:state.step}));}
function changeCurrent(o){state.current=o;$('#selected-title').textContent=titleOf(o);$('#selected-eco').textContent=o.eco;$('#selected-description').textContent=descriptionOf(o);renderSelectedFavorite();}
function jump(step,{resetTree=true}={}){if(!state.current)return;state.step=Math.max(0,Math.min(Number.isFinite(step)?Math.trunc(step):0,state.current.moves.length));state.game=new Chess();state.current.moves.slice(0,state.step).forEach(m=>state.game.move(m));if(resetTree){state.treeRoot=state.tree.find(currentPath());state.expanded=new Set();state.limits.clear();}renderBoard();renderMoves();renderTree();renderCommonVariations();opponent.sync(state.current,state.step,state.game);updateHash();}
function selectOpening(id,step,panel='steps'){const opening=state.data.find(o=>o.id===Number(id));if(!opening)return;changeCurrent(opening);$('#move-list').scrollTop=0;jump(step??opening.moves.length);renderList();setPanel(panel);}
function renderCommonVariations(){const family=state.current.name.split(':')[0],items=commonVariations(state.data,state.current);$('#variations-title').textContent=`${families[family]||family} · 常见变例`;$('#variation-count').textContent=`${items.length} 个入口`;$('#common-variations').innerHTML=items.length?items.map(({label,opening:o})=>{const path=currentPath(),difference=firstDifferentStep(path,o.moves),relation=isPrefix(path,o.moves)?'查看完整走法':isPrefix(o.moves,path)?'返回主干走法':`从第 ${difference} 步分出`;return `<button class="variation-chip ${state.current.id===o.id?'active':''}" data-variation="${o.id}" aria-label="选择变例 ${esc(label)}" title="${esc(titleOf(o))}"><strong>${esc(label)}</strong><small>${relation}</small></button>`;}).join(''):'<p class="no-variations">此体系暂无独立变例入口，可从下方走法树探索。</p>';}
function nodeLabel(node){if(!node.endings.length)return '';const opening=[...node.endings].sort((a,b)=>a.name.length-b.name.length)[0];return variationOf(opening)||families[opening.name.split(':')[0]]||opening.name;}
function renderChildren(parent){
 const children=[...parent.children.values()].sort((a,b)=>b.count-a.count||a.move.localeCompare(b.move)),limit=state.limits.get(parent.id)||8;let html='<ul class="branch-children">';
 for(const n of children.slice(0,limit)){const expanded=state.expanded.has(n.id),hasChildren=n.children.size>0,active=n.path.length===state.step&&isPrefix(n.path,state.current.moves),onLine=isPrefix(n.path,state.current.moves),info=movesFor(n.best)[n.path.length-1],label=nodeLabel(n)||info.description;html+=`<li class="branch-item"><div class="branch-row ${active?'active':''} ${onLine?'on-line':''}">${hasChildren?`<button class="branch-toggle ${expanded?'expanded':''}" data-expand="${n.id}" aria-expanded="${expanded}" aria-label="${expanded?'收起':'展开'} ${moveNumber(n.path.length)}${esc(n.move)} 的后续分支">${icon('right')}</button>`:'<span class="branch-leaf" aria-hidden="true">·</span>'}<button class="branch-select" data-node="${n.id}" aria-current="${active?'step':'false'}" aria-label="跳到分支 ${moveNumber(n.path.length)}${esc(n.move)}"><span class="branch-move"><strong>${moveNumber(n.path.length)}${esc(n.move)}</strong>${onLine?'<span class="line-dot" title="在所选棋谱中"></span>':''}</span><span class="branch-label">${esc(label)}</span></button><span class="branch-count" title="包含此着法顺序的收录棋谱">${n.count.toLocaleString()}</span></div>${expanded&&hasChildren?renderChildren(n):''}</li>`;}if(children.length>limit)html+=`<li><button class="more-branches" data-more="${parent.id}">再显示 ${children.length-limit} 个分支</button></li>`;return html+'</ul>';
}
function renderTree(){if(!state.treeRoot)return;const root=state.treeRoot;$('#tree-title').textContent=root.path.length?`第 ${root.path.length} 步之后的变招`:'从初始局面探索';let crumbs='<button data-tree-root="0">初始局面</button>',path=[];for(const move of root.path){path.push(move);const node=state.tree.find(path);crumbs+=`<span>›</span><button data-tree-root="${node.id}">${moveNumber(path.length)}${esc(move)}</button>`;}$('#tree-breadcrumb').innerHTML=crumbs;$('#tree-root-caption').textContent=`${root.children.size} 种下一步 · ${root.count.toLocaleString()} 条相关棋谱`;$('#tree-recenter').hidden=isPrefix(root.path,currentPath())&&root.path.length===state.step;$('#variation-tree').innerHTML=root.children.size?renderChildren(root):`<div class="tree-end"><span>◇</span><b>已到这条命名棋谱的末尾</b><p>点击完整着法中的任一步，查看当时的其他分支；也可以选择上方的常见变例。</p>${root.parent!==null?`<button class="text-button" data-tree-root="${root.parent}">回到上一步看分支 ${icon('left')}</button>`:''}</div>`;}
function chooseNode(id,{recenter=false}={}){const node=state.tree.nodes[Number(id)];if(!node)return;if(!isPrefix(node.path,state.current.moves)){changeCurrent(node.best);$('#move-list').scrollTop=0;renderList();}if(recenter){state.treeRoot=node;state.expanded=new Set();state.limits.clear();}else{let ancestor=node;while(ancestor&&ancestor.id!==state.treeRoot.id){state.expanded.add(ancestor.id);ancestor=state.tree.nodes[ancestor.parent];}}jump(node.path.length,{resetTree:false});}
function resetFilters(){state.query='';state.eco='';state.category='';state.page=1;$('#search').value='';$('#eco-filter').value='';}
document.addEventListener('click',e=>{
 const fav=e.target.closest('[data-favorite]');if(fav){toggleFavorite(Number(fav.dataset.favorite));return;}
 const step=e.target.closest('[data-step]');if(step){jump(Number(step.dataset.step));return;}
 const expand=e.target.closest('[data-expand]');if(expand){const id=Number(expand.dataset.expand);state.expanded.has(id)?state.expanded.delete(id):state.expanded.add(id);renderTree();return;}
 const more=e.target.closest('[data-more]');if(more){state.limits.set(Number(more.dataset.more),Infinity);renderTree();return;}
 const root=e.target.closest('[data-tree-root]');if(root){chooseNode(root.dataset.treeRoot,{recenter:true});return;}
 const node=e.target.closest('[data-node]');if(node){chooseNode(node.dataset.node);return;}
 const variation=e.target.closest('[data-variation]');if(variation){selectOpening(variation.dataset.variation,undefined,'tree');return;}
 const panel=e.target.closest('[data-panel]');if(panel){setPanel(panel.dataset.panel);return;}
 const card=e.target.closest('[data-id]');if(card){selectOpening(card.dataset.id);return;}
 const view=e.target.closest('[data-view]');if(view){state.view=view.dataset.view;resetFilters();renderList();setPanel('library');return;}
 const tab=e.target.closest('[data-tab]');if(tab){state.view='library';state.tab=tab.dataset.tab;resetFilters();renderList();return;}
 const category=e.target.closest('[data-category]');if(category){state.view='library';const previous=state.category;resetFilters();state.category=previous===category.dataset.category?'':category.dataset.category;state.tab='all';renderList();setPanel('library');return;}
 if(e.target.closest('#clear-filters')){state.view='library';state.tab='all';resetFilters();renderList();}if(e.target.closest('#remove-category')){state.category='';state.page=1;renderList();}
});
$('#search').addEventListener('input',e=>{state.query=e.target.value.trim();state.page=1;renderList();});$('#eco-filter').addEventListener('change',e=>{state.eco=e.target.value;state.page=1;renderList();});$('#favorite-selected').addEventListener('click',()=>toggleFavorite(state.current.id));$('#flip-board').addEventListener('click',()=>{state.flipped=!state.flipped;renderBoard();});$('#tree-recenter').addEventListener('click',()=>chooseNode(state.tree.find(currentPath()).id,{recenter:true}));
$('#random-opening').addEventListener('click',()=>{const pool=results().filter(o=>o.id!==state.current?.id);if(pool.length)selectOpening(pool[Math.floor(Math.random()*pool.length)].id);else toast('当前范围没有更多开局，可以尝试清除筛选');});$('#page-prev').addEventListener('click',()=>{state.page--;renderList();$('#opening-list').scrollTop=0;});$('#page-next').addEventListener('click',()=>{state.page++;renderList();$('#opening-list').scrollTop=0;});
for(const id of ['guide-open','about-open'])$('#'+id).addEventListener('click',()=>$('#guide').showModal());for(const el of document.querySelectorAll('#guide .dialog-close,#guide-start'))el.addEventListener('click',()=>$('#guide').close());$('#guide').addEventListener('click',e=>{if(e.target===$('#guide')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)e.target.close();}});
$('#cover-open').addEventListener('click',()=>$('#cover-dialog').showModal());$('#cover-close').addEventListener('click',()=>$('#cover-dialog').close());
// Tabs support arrow-key navigation without moving the page.
$('.inspector-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();e.stopPropagation();const tabs=[...document.querySelectorAll('[data-panel]')],index=tabs.indexOf(document.activeElement),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;setPanel(tabs[next].dataset.panel);tabs[next].focus();});
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||document.querySelector('dialog[open]')||!state.current)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();jump(state.step+(e.key==='ArrowRight'?1:-1));}else if(e.key.toLowerCase()==='f'){state.flipped=!state.flipped;renderBoard();}else if(e.key==='/'){e.preventDefault();setPanel('library');$('#search').focus();}});
async function init(){try{const response=await fetch('./openings.json');if(!response.ok)throw Error('Opening data unavailable');state.data=await response.json();state.data.forEach(o=>o.search=searchable(o));state.featured=selectFeatured(state.data);state.tree=buildOpeningTree(state.data);favorites=new Set([...favorites].filter(id=>state.data.some(o=>o.id===id)));$('#favorite-count').textContent=favorites.size;$('#total-stat').textContent=state.data.length.toLocaleString();const params=new URLSearchParams(location.hash.slice(1)),requested=params.has('opening')&&state.data.find(o=>o.id===Number(params.get('opening'))),step=params.has('step')?Number(params.get('step')):undefined;selectOpening(requested?.id??state.featured[0].id,Number.isFinite(step)?step:undefined);setPanel('steps');}catch(error){console.error('Opening library could not load',error);setPanel('tree');$('#variation-tree').innerHTML='<div class="empty-state">开局数据加载失败<p>请检查网络后重新加载页面。</p><button id="reload-library">重新加载</button></div>';$('#reload-library').addEventListener('click',()=>location.reload());}}
init();

